import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { Chart as ChartJS, ArcElement, Tooltip, Legend, CategoryScale, LinearScale, BarElement } from 'chart.js';
import { Pie, Bar } from 'react-chartjs-2';
import { TrendingUp, Award, Target, CalendarCheck, Sparkles } from 'lucide-react';
import { motion } from 'framer-motion';
import axios from 'axios';

ChartJS.register(ArcElement, Tooltip, Legend, CategoryScale, LinearScale, BarElement);

const ProgressStats = () => {
    const { user, token } = useAuth();
    const [stats, setStats] = useState(null);
    const [tasks, setTasks] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (user) {
            fetchData();
        }
    }, [user]);

    const fetchData = async () => {
        try {
            const tasksRes = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            console.log('📊 Tasks data:', tasksRes.data);
            setTasks(tasksRes.data);

            const statsRes = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}/progress`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            console.log('📊 Stats data:', statsRes.data);
            setStats(statsRes.data);
            setLoading(false);
        } catch (error) {
            console.error('❌ Failed to fetch data:', error);
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-500"></div>
            </div>
        );
    }

    // 📊 REAL DATA FROM DATABASE
    const totalTasks = tasks.length;
    const completedTasks = tasks.filter(t => t.overallCompleted === true).length;
    const completionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

    // Task-wise completion
    const javaCompleted = tasks.filter(t => t.javaCompleted === true).length;
    const leetcodeCompleted = tasks.filter(t => t.leetcodeCompleted === true).length;
    const dsaCompleted = tasks.filter(t => t.dsaCompleted === true).length;
    const sqlCompleted = tasks.filter(t => t.sqlCompleted === true).length;
    const projectCompleted = tasks.filter(t => t.projectCompleted === true).length;
    const githubCompleted = tasks.filter(t => t.githubCompleted === true).length;

    // Calculate streak
    const calculateStreak = () => {
        let streak = 0;
        const sortedTasks = [...tasks].sort((a, b) => a.day - b.day);
        for (const task of sortedTasks) {
            if (task.overallCompleted === true) {
                streak++;
            } else {
                break;
            }
        }
        return streak;
    };

    const streak = calculateStreak();

    const pieData = {
        labels: ['Completed ✅', 'Remaining ⏳'],
        datasets: [
            {
                data: [completedTasks, Math.max(0, totalTasks - completedTasks)],
                backgroundColor: ['#34d399', '#e5e7eb'],
                borderWidth: 0,
            },
        ],
    };

    const barData = {
        labels: ['Java', 'LeetCode', 'DSA', 'SQL/API', 'Project', 'GitHub'],
        datasets: [
            {
                label: 'Tasks Completed',
                data: [javaCompleted, leetcodeCompleted, dsaCompleted, sqlCompleted, projectCompleted, githubCompleted],
                backgroundColor: [
                    '#4f8cf7',
                    '#7c5cfc',
                    '#34d399',
                    '#fb923c',
                    '#f472b6',
                    '#06b6d4',
                ],
                borderRadius: 6,
            },
        ],
    };

    const chartOptions = {
        responsive: true,
        plugins: {
            legend: {
                labels: {
                    color: '#6a6a82',
                    font: {
                        family: 'Inter',
                        size: 12,
                    },
                },
            },
        },
        scales: {
            y: {
                beginAtZero: true,
                grid: {
                    color: '#f0f0f0',
                },
                ticks: {
                    color: '#6a6a82',
                },
            },
            x: {
                grid: {
                    display: false,
                },
                ticks: {
                    color: '#6a6a82',
                },
            },
        },
    };

    const statsCards = [
        { label: 'Completion Rate', value: `${completionRate}%`, icon: TrendingUp, color: 'text-green-500', bg: 'bg-green-50' },
        { label: 'Tasks Done', value: `${completedTasks}/${totalTasks}`, icon: CalendarCheck, color: 'text-indigo-500', bg: 'bg-indigo-50' },
        { label: 'Streak', value: `${streak} days`, icon: Award, color: 'text-orange-500', bg: 'bg-orange-50' },
        { label: 'Target', value: '30 days', icon: Target, color: 'text-purple-500', bg: 'bg-purple-50' },
    ];

    return (
        <div className="space-y-6 max-w-7xl mx-auto">
            {/* Header */}
            <motion.div 
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="relative overflow-hidden rounded-2xl p-6 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500"
            >
                <div className="absolute top-0 right-0 w-48 h-48 bg-white/10 rounded-full blur-3xl"></div>
                <div className="relative flex items-center gap-3">
                    <Sparkles size={28} className="text-white" />
                    <div>
                        <h1 className="text-2xl font-bold text-white">📊 Progress Analytics</h1>
                        <p className="text-white/70 text-sm">Track your learning journey</p>
                    </div>
                </div>
            </motion.div>

            {/* Stats Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                {statsCards.map((stat, index) => {
                    const Icon = stat.icon;
                    return (
                        <motion.div
                            key={index}
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ delay: index * 0.1 }}
                            className="bg-white rounded-2xl p-6 shadow-sm border border-gray-100 hover:shadow-md transition"
                        >
                            <div className="flex items-center justify-between">
                                <div>
                                    <p className="text-sm text-gray-500">{stat.label}</p>
                                    <p className="text-2xl font-bold text-gray-800 mt-1">{stat.value}</p>
                                </div>
                                <div className={`${stat.bg} p-3 rounded-lg`}>
                                    <Icon className={stat.color} size={24} />
                                </div>
                            </div>
                        </motion.div>
                    );
                })}
            </div>

            {/* Charts */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <motion.div 
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    className="bg-white rounded-2xl p-6 shadow-sm border border-gray-100"
                >
                    <h2 className="text-lg font-semibold text-gray-800 mb-4">📊 Overall Completion</h2>
                    <div className="max-w-xs mx-auto">
                        <Pie data={pieData} options={chartOptions} />
                    </div>
                    <div className="text-center mt-4">
                        <p className="text-sm text-gray-500">
                            {completedTasks} of {totalTasks} tasks completed
                        </p>
                        {totalTasks === 0 && (
                            <p className="text-sm text-orange-500 mt-2">
                                ⚠️ No tasks found! Go to Daily Tracker and create tasks.
                            </p>
                        )}
                    </div>
                </motion.div>

                <motion.div 
                    initial={{ opacity: 0, x: 20 }}
                    animate={{ opacity: 1, x: 0 }}
                    className="bg-white rounded-2xl p-6 shadow-sm border border-gray-100"
                >
                    <h2 className="text-lg font-semibold text-gray-800 mb-4">📊 Task-wise Completion</h2>
                    <Bar
                        data={barData}
                        options={{
                            ...chartOptions,
                            plugins: {
                                legend: {
                                    display: false,
                                },
                            },
                            scales: {
                                y: {
                                    beginAtZero: true,
                                    grid: {
                                        color: '#f0f0f0',
                                    },
                                    ticks: {
                                        color: '#6a6a82',
                                        stepSize: 1,
                                    },
                                },
                                x: {
                                    grid: {
                                        display: false,
                                    },
                                    ticks: {
                                        color: '#6a6a82',
                                    },
                                },
                            },
                        }}
                    />
                    {totalTasks === 0 && (
                        <p className="text-center text-sm text-orange-500 mt-4">
                            ⚠️ No data to display. Create tasks in Daily Tracker!
                        </p>
                    )}
                </motion.div>
            </div>

            {/* Motivation Section */}
            <motion.div 
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="relative overflow-hidden rounded-2xl p-8 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500"
            >
                <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full blur-3xl"></div>
                <div className="absolute bottom-0 left-0 w-48 h-48 bg-white/10 rounded-full blur-2xl"></div>
                
                <div className="relative">
                    <h2 className="text-2xl font-bold text-white mb-2">🚀 Keep Going!</h2>
                    <p className="text-white/80 text-base">
                        You're making great progress! Remember: Consistency is key to mastering development skills.
                    </p>
                    <div className="mt-4 flex gap-4 flex-wrap">
                        <span className="px-3 py-1 bg-white/20 rounded-full text-sm text-white">#CodeEveryday</span>
                        <span className="px-3 py-1 bg-white/20 rounded-full text-sm text-white">#NeverGiveUp</span>
                        <span className="px-3 py-1 bg-white/20 rounded-full text-sm text-white">#YouCanDoIt</span>
                        <span className="px-3 py-1 bg-white/20 rounded-full text-sm text-white">#StayConsistent</span>
                    </div>
                </div>
            </motion.div>
        </div>
    );
};

export default ProgressStats;
